package com.aidevos.orchestrator.qualitygate;
import java.time.Instant; import java.util.ArrayList; import java.util.LinkedHashMap; import java.util.List; import java.util.Map;
public class QualityGateResult {
	private String gateResultId,validationRunId,taskId,projectId,workspaceId,policyVersion,evidenceFingerprint,approvalId;
	private QualityGateDecision decision; private QualityGateStatus status=QualityGateStatus.EVALUATED;
	private List<QualityGateReason> reasons=new ArrayList<>(); private Map<String,Object> securitySummary=new LinkedHashMap<>(),validationSummary=new LinkedHashMap<>(); private Instant createdAt,decidedAt;
	public String getGateResultId(){return gateResultId;} public void setGateResultId(String v){gateResultId=v;} public String getValidationRunId(){return validationRunId;} public void setValidationRunId(String v){validationRunId=v;} public String getTaskId(){return taskId;} public void setTaskId(String v){taskId=v;} public String getProjectId(){return projectId;} public void setProjectId(String v){projectId=v;} public String getWorkspaceId(){return workspaceId;} public void setWorkspaceId(String v){workspaceId=v;} public String getPolicyVersion(){return policyVersion;} public void setPolicyVersion(String v){policyVersion=v;} public String getEvidenceFingerprint(){return evidenceFingerprint;} public void setEvidenceFingerprint(String v){evidenceFingerprint=v;} public String getApprovalId(){return approvalId;} public void setApprovalId(String v){approvalId=v;} public QualityGateDecision getDecision(){return decision;} public void setDecision(QualityGateDecision v){decision=v;} public QualityGateStatus getStatus(){return status;} public void setStatus(QualityGateStatus v){status=v;} public List<QualityGateReason> getReasons(){return reasons;} public void setReasons(List<QualityGateReason> v){reasons=v==null?new ArrayList<>():new ArrayList<>(v);} public Map<String,Object> getSecuritySummary(){return securitySummary;} public void setSecuritySummary(Map<String,Object> v){securitySummary=v==null?new LinkedHashMap<>():new LinkedHashMap<>(v);} public Map<String,Object> getValidationSummary(){return validationSummary;} public void setValidationSummary(Map<String,Object> v){validationSummary=v==null?new LinkedHashMap<>():new LinkedHashMap<>(v);} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getDecidedAt(){return decidedAt;} public void setDecidedAt(Instant v){decidedAt=v;}
}
